# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('relinquish','/rɪˈlɪŋkwɪʃ/','放弃；交出；不再保有','原来抓在手里的权力、位置或控制，现在松手，让它离开自己。','拉丁 re- 向后 + linquere 留下，组成 relinquere 留在身后、放弃；经古法语 relinquir 的 relinquiss- 词形进入英语。-ish 在这里不是表示有点的后缀。',[['拉丁 linquere → relinquere','留下 → 留在身后、放弃'],['古法语 relinquir、relinquiss- → 英语 relinquish','放弃、不再占有或坚持']],'常见对象是 control、power、a position：过去由你掌握的东西，如今不再掌握。它比 give up 正式，也不必带失败感；你可以主动交权，也可能在压力下被迫放弃。','relinquish control；relinquish power；relinquish a claim；reluctantly relinquish。','resign 通常是辞去职位；relinquish 可交出职位、权力、控制或主张，范围更广。reluctant 不愿意并不是这个词拆出来的部分。',('She was reluctant to relinquish control of the project.','她不愿放弃对这个项目的控制。'),('He relinquished his seat on the committee.','他辞去了委员会中的职务。'),sources=['https://www.etymonline.com/word/relinquish']),
E('relinquishment','/rɪˈlɪŋkwɪʃmənt/','放弃；交出','把松手这个动作当作一件事来讨论：交出什么，何时交出。','英语 relinquish + -ment 名词结尾。',[['英语 relinquish','放弃、交出'],['英语 relinquishment','放弃或交出这一行为']],'the relinquishment of control 就是交出控制权这件事，常见于正式说明和组织变更的讨论。日常聊天直接用 give up 或 relinquish 的动词句，通常更轻便。','the relinquishment of power；voluntary relinquishment；relinquishment of control。','relinquishment 讲原有的东西不再保有；refusal 讲拒绝接受或拒绝做。没接过与接过后放手是两种情况。',('The plan required the founder’s relinquishment of day-to-day control.','这个计划要求创始人交出日常管理权。'),('Her relinquishment of the role was entirely voluntary.','她完全自愿放弃了这一职务。'),sources=['https://www.etymonline.com/word/relinquish','https://en.wiktionary.org/wiki/relinquishment#English']),
E('relic','/ˈrelɪk/','遗物；遗迹；旧时代留下的东西；圣物','人或时代已经过去，一件东西却留了下来。','来自古法语 relique，前身是拉丁 reliquiae 遗留物，与 reliquus 剩下的、relinquere 留下相关。早期英语常指宗教圣物，后来泛指过去的遗留物。',[['拉丁 linquere、relinquere；相关 reliquus','留下；剩下的'],['拉丁 reliquiae → 古法语 relique','遗留物；尤其受尊奉的宗教遗物'],['英语 relic','圣物；旧时代的物品、遗留习惯或观念']],'an old railway relic 可以是一段旧铁路遗存；a relic of the past 也能说一种还没退出舞台的老制度。圣人的遗骨或相关物品也叫 relic，这时带宗教敬奉的含义。','a relic of the past；ancient relics；a religious relic。','artifact 强调人造物品；relic 强调从过去留到现在。calling something a relic 有时是在说它陈旧过时，不总是赞美有历史价值。',('The museum displays relics from the old railway.','博物馆陈列着旧铁路留下的物品。'),('He sees the rule as a relic of a different era.','他认为这条规定是另一个时代留下的陈规。'),sources=['https://www.etymonline.com/word/relic']),
E('derelict','/ˈderəlɪkt/','荒废的；被遗弃的；失职的','东西被丢下后长期没人管，房屋会荒废，职责也会被搁置。','拉丁 de- 加强 + relinquere 放弃，形成 derelinquere；其过去分词 derelictus 表示被遗弃的，英语据此借入。',[['拉丁 relinquere → derelinquere','留下、放弃 → 遗弃'],['拉丁 derelictus → 英语 derelict','被遗弃的 → 荒废的；也用于失职']],'a derelict factory 往往是废弃且失修的工厂，不仅是今天没开门。be derelict in one’s duty 则说没有尽到职责。这个词作名词称人时带贬损意味，普通介绍一个人的处境时不宜当作中性称呼。','a derelict building；derelict land；be derelict in one’s duty。','abandoned 强调被弃置；derelict 常多一层长期无人维护的破败感。empty 只说里面没人或没东西。',('The derelict factory was converted into a community centre.','这座废弃工厂被改成了社区中心。'),('The report said the manager had been derelict in his duty.','报告指出，这位经理没有尽到职责。'),sources=['https://www.etymonline.com/word/derelict','https://en.wiktionary.org/wiki/derelict#English']),
E('dereliction','/ˌderəˈlɪkʃən/','荒废；弃置；失职','该照管的地方没照管，该履行的职责也被放在一边。','借自拉丁 derelictio、dereliction- 遗弃、忽略，来自 derelinquere 的分词词干。英语名词的记录早于形容词 derelict，不把历史写成英语形容词加 -ion 才出现。',[['拉丁 derelinquere → derelictio','遗弃、忽略 → 遗弃或忽略这一行为'],['英语 dereliction','荒废状态；后来常指失职']],'最常见的完整搭配是 dereliction of duty，语气严肃，指该做的职责没有履行。years of dereliction 则可以描写建筑多年无人维护后的荒废状态。','dereliction of duty；years of dereliction；a state of dereliction。','neglect 更通用，能说忽视各种人或事；dereliction 更正式，常集中在职责或荒废场所上。',('The inquiry described the failure as a dereliction of duty.','调查把这次失误认定为没有尽到职责。'),('After years of dereliction, the gardens were restored.','荒废多年后，这些花园得到了修复。'),sources=['https://www.etymonline.com/word/dereliction']),
E('delinquent','/dɪˈlɪŋkwənt/','有违法或越轨行为的；未履行义务的；逾期未付的','该守的规矩或该完成的义务，被落下了。','来自拉丁 delinquere 未做到、犯错的现在分词 delinquens、delinquent-；其中 de- 加强，linquere 留下。并不是英语 delin 加一个后缀。',[['拉丁 linquere → delinquere','留下 → 未做到、犯错'],['拉丁 delinquens、delinquent- → 英语 delinquent','未履行义务的；也作指犯错者的名词']],'juvenile delinquent 常指有违法行为的未成年人；delinquent payments 则是到期没付的钱。共同点不是调皮，而是没有履行某种要求。讨论青少年时，用具体行为描述通常比随手贴 delinquent 标签更清楚。','juvenile delinquent；delinquent behaviour；delinquent payments；a delinquent account。','late 只是迟；delinquent 更正式，涉及义务未履行。不能把所有晚到的人都叫 delinquent。',('The report examines factors linked to delinquent behaviour.','报告分析了与违法越轨行为相关的因素。'),('The system flags delinquent payments for review.','系统把逾期未付的款项标记出来，供进一步核查。'),sources=['https://www.etymonline.com/word/delinquent','https://en.wiktionary.org/wiki/delinquent#English']),
E('delinquency','/dɪˈlɪŋkwənsi/','违法越轨行为；未履行义务；逾期欠付','把没有履行要求的行为或状态作为一个整体来讨论。','借自晚期拉丁 delinquentia 过错、违法，与 delinquens 未履行义务的这一分词词干有关。学习时把它和 delinquent 成对记，但历史上有自己的名词来源。',[['拉丁 delinquere → delinquent-','未做到、犯错 → 未履行的'],['晚期拉丁 delinquentia → 英语 delinquency','过错、违法或未尽义务的状态']],'juvenile delinquency 是青少年违法问题；payment delinquency 是款项未按期支付。一个是行为研究，一个是付款状态，具体含义要看前后的名词。','juvenile delinquency；reduce delinquency；payment delinquency。','delinquent 可形容人、行为或款项；delinquency 把现象作为名词讨论。delinquency 不自动等于所有意义上的 crime。',('The programme aims to reduce juvenile delinquency.','这个项目旨在减少青少年违法行为。'),('The report tracks payment delinquency over time.','这份报告追踪款项逾期未付的变化情况。'),sources=['https://www.etymonline.com/word/delinquency','https://en.wiktionary.org/wiki/delinquency#English'])]
ROOT=dict(id='C0678',meaning='留下；放下；未做到',core='LINQU / LICT = LEAVE',image='松手后东西留在身后：放手是 relinquish，留下的旧物是 relic；把地方或责任丢着不管，就走向 derelict 和 delinquent。',intro='拉丁 linquere 表示留下。它与前缀结合后，既能说放弃占有，也能说遗漏职责；分词等词形又留下 lict-、liqu- 等变化。',forms='linquere → relinquere；relinquere 的分词是 relictus。derelinquere 的分词是 derelictus；delinquere 的现在分词词干是 delinquent-。这些是拉丁语内部的变化，不是英语单词任意改几下拼写。',branches=[['松手、交出','relinquish','relinquishment'],['从过去留下的东西','relic'],['荒废或忽略职责','derelict','dereliction'],['没有履行要求','delinquent','delinquency']],contrasts='relic 不一定荒废，它可以被珍藏；derelict 常有无人维护的意思。relinquish 可以是妥善交权，delinquent 则带未尽要求或义务的意思。',practice='The derelict station is a relic of the old railway.\n\n这座废弃车站是旧铁路留下的遗存。',words=[x['word'] for x in W],exclude={'relict':'旧式遗孀用法及生态地理专门用法，先略过，优先掌握 relic。'})
ROOT['branches']=[[x[0],'；'.join(x[1:])] for x in ROOT['branches']]
if __name__=='__main__':
 for name,data in [('roots_linqu',[ROOT]),('words_linqu',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
